def overlap_minutes(meetings: list[list[int]], k: int) -> int:
    if not meetings:
        return 0

    events = []
    for start, end in meetings:
        if start < end:
            events.append((start, 1))
            events.append((end, -1))

    if not events:
        return 0

    events.sort()

    total = 0
    count = 0
    prev_time = events[0][0]

    for time, delta in events:
        if time > prev_time:
            if count >= k:
                total += time - prev_time
            prev_time = time
        count += delta

    return total
